import { config } from "dotenv";
config({ path: ".env.local", quiet: true });
import { createAdminClient } from "./supabaseAdmin";

// One-time cleanup of the canonical `ingredients` table, reviewed by hand
// against each entry's recipe_ingredients.raw_text (not generated by an LLM
// call — dumped from the DB, read, and decided on manually). Fixes three
// kinds of accumulated cruft:
//   - RENAME_MAP: garbled leftovers of a failed quantity/unit parse (e.g.
//     "or 2 scallions", "to 10 dumplings") corrected to the real ingredient
//     name, plus singular/plural duplicates ("scallions" -> "scallion")
//     collapsed to one canonical form. If the target name already exists as
//     a different ingredient, this is a merge (recipe_ingredients and
//     grocery_list_items repointed, the source row deleted); otherwise it's
//     an in-place rename. name_fr is cleared on rename so `npm run
//     translate` retranslates it.
//   - FLAG_NAMES: not ingredients at all (recipe notes/instructions/titles
//     a scrape mistakenly captured as an ingredient line) — reported only,
//     never auto-deleted, since removing the row would also drop its
//     raw_text with no way to recover it short of a re-scrape.
//   - DELETE_NAMES: canonical rows with zero referencing recipe_ingredients
//     or grocery_list_items rows already (dead data, e.g. from a recipe
//     that was later removed) — deleted outright after verifying the
//     reference count really is zero.

