// Recipe notes/instructions/titles that a scrape mistakenly captured as an
// ingredient line. Reported for manual review, never auto-deleted.
const FLAG_NAMES = [
  "Black Sesame Dan Dan Noodles",
  "Makes 7 to 9 about 3-inch fritters",
  "Double this if you want to serve with a sauce.",
  "Makes about 40 dumplings",
  "Makes 16 pieces",
  "Visit the links provided above for the ingredients for each soup.",
  "Visit the links provided above for the ingredients for each recipe.",
  "If the sauce is too thick, use a tablespoon of water or soda to thin it.",
  "Mix all sauce ingredients well and set aside.",
  "Makes 2 large pancakes or 6 small ones",
  "Pork Shabu Shabu and Cold Somen with Sesame Miso Sauce",
  "Dissolve 1/2 cup coarse salt in 4 cups of water, and soak the cabbage leaves until softened, 2 to 4 hours. Rinse and drain well.",
];

// Already unreferenced by any recipe_ingredients/grocery_list_items row
// (dead data — verified again at run time before deleting).
const DELETE_NAMES = [
  "-3 lotus root",
  "to 2.5 pounds fresh white fish fillets",
  "to 12 Korean white cucumbers",
  "to 3 cups sliced rice cakes",
  "to 10 dumplings",
  "to 5 pounds or about 15 small to medium young radishes with leaves",
  "/4 cups all purpose flour",
  "- ⅓ cup water",
];

interface Args {
  dryRun: boolean;
}

function parseArgs(): Args {
  return { dryRun: process.argv.includes("--dry-run") };
}

async function main() {
  const args = parseArgs();
  const admin = createAdminClient();

  const PAGE_SIZE = 1000;
  const nameToId = new Map<string, string>();
  for (let from = 0; ; from += PAGE_SIZE) {
    const { data, error } = await admin
      .from("ingredients")
      .select("id, name")
      .range(from, from + PAGE_SIZE - 1);
    if (error) throw new Error(`select ingredients failed: ${error.message}`);
    for (const ing of data ?? []) nameToId.set(ing.name, ing.id);
    if (!data || data.length < PAGE_SIZE) break;
  }

  let renamed = 0;
  let merged = 0;
  let failed = 0;

  for (const [oldName, newName] of Object.entries(RENAME_MAP)) {
    const id = nameToId.get(oldName);
    if (!id) {
      console.warn(`  skip: "${oldName}" not found (already fixed or renamed?)`);
      continue;
    }

    const collisionId = nameToId.get(newName);
    const isMerge = collisionId !== undefined && collisionId !== id;
    const label = `"${oldName}" -> "${newName}"${isMerge ? " (merge)" : ""}`;

    if (args.dryRun) {
      console.log(label);
      if (isMerge) merged++;
      else renamed++;
      continue;
    }

    try {
      if (isMerge) {
        const targetId = collisionId!;
        const { error: e1 } = await admin
          .from("recipe_ingredients")
          .update({ ingredient_id: targetId })
          .eq("ingredient_id", id);
        if (e1) throw new Error(e1.message);
        const { error: e2 } = await admin
          .from("grocery_list_items")
          .update({ ingredient_id: targetId })
          .eq("ingredient_id", id);
        if (e2) throw new Error(e2.message);
        const { error: e3 } = await admin.from("ingredients").delete().eq("id", id);
        if (e3) throw new Error(e3.message);
        merged++;
      } else {
        const { error: e1 } = await admin
          .from("ingredients")
          .update({ name: newName, name_fr: null })
          .eq("id", id);
        if (e1) throw new Error(e1.message);
        nameToId.set(newName, id);
        renamed++;
      }
      console.log(label);
    } catch (err) {
      console.warn(`  failed: ${label}: ${(err as Error).message}`);
      failed++;
    }
  }

  let deleted = 0;
  for (const name of DELETE_NAMES) {
    const id = nameToId.get(name);
    if (!id) {
      console.warn(`  skip delete: "${name}" not found`);
      continue;
    }
    const { count: riCount } = await admin
      .from("recipe_ingredients")
      .select("id", { count: "exact", head: true })
      .eq("ingredient_id", id);
    const { count: gliCount } = await admin
      .from("grocery_list_items")
      .select("id", { count: "exact", head: true })
      .eq("ingredient_id", id);
    if ((riCount ?? 0) > 0 || (gliCount ?? 0) > 0) {
      console.warn(`  skip delete: "${name}" is still referenced (${riCount} recipe_ingredients, ${gliCount} grocery_list_items)`);
      continue;
    }
    if (args.dryRun) {
      console.log(`delete  "${name}"`);
      deleted++;
      continue;
    }
    const { error: delError } = await admin.from("ingredients").delete().eq("id", id);
    if (delError) {
      console.warn(`  failed to delete "${name}": ${delError.message}`);
      failed++;
      continue;
    }
    console.log(`deleted "${name}"`);
    deleted++;
  }

  console.log(
    `\nfix-ingredient-names: ${renamed} renamed, ${merged} merged, ${deleted} deleted, ${failed} failed${args.dryRun ? " (dry run — no writes)" : ""}`,
  );
  console.log(`${FLAG_NAMES.length} flagged as not real ingredients (needs manual review, not touched):`);
  for (const name of FLAG_NAMES) {
    const id = nameToId.get(name);
    console.log(`  ${id ?? "(not found)"}  ${JSON.stringify(name)}`);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
